-- ============================================================
-- Q9 Hotel Room Booking System  |  Database: hotel_db
-- Tables: guest, room, booking  (InnoDB, with PK/FK)
-- Import via phpMyAdmin -> Import tab
-- ============================================================
CREATE DATABASE IF NOT EXISTS hotel_db;
USE hotel_db;

DROP TABLE IF EXISTS booking;
DROP TABLE IF EXISTS room;
DROP TABLE IF EXISTS guest;

CREATE TABLE guest (
    guest_id INT PRIMARY KEY,
    name     VARCHAR(100) NOT NULL,
    city     VARCHAR(60)  NOT NULL,
    phone    VARCHAR(15)  NOT NULL
) ENGINE=InnoDB;

CREATE TABLE room (
    room_no        INT PRIMARY KEY,
    room_type      VARCHAR(30)   NOT NULL,
    tariff_per_day DECIMAL(10,2) NOT NULL,
    floor          INT           NOT NULL
) ENGINE=InnoDB;

CREATE TABLE booking (
    booking_id INT AUTO_INCREMENT PRIMARY KEY,
    guest_id   INT  NOT NULL,
    room_no    INT  NOT NULL,
    check_in   DATE NOT NULL,
    check_out  DATE NOT NULL,
    CONSTRAINT fk_booking_guest FOREIGN KEY (guest_id) REFERENCES guest(guest_id),
    CONSTRAINT fk_booking_room  FOREIGN KEY (room_no)  REFERENCES room(room_no)
) ENGINE=InnoDB;



